import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class ContractTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void exactOrderMultiplicityAndPreservation(){Object a=TaskBinding.book(1,new String[]{"Ann Lee"},"P",2020),b=TaskBinding.book(2,new String[]{"Ann"},"Q",2021);Object[]in=TaskBinding.array(a,b,a);String sa=TaskBinding.state(a),sb=TaskBinding.state(b);assertValues(new Object[]{a,a},select(in,()->TaskBinding.author(in,"Ann Lee")));assertValues(new Object[]{b},select(in,()->TaskBinding.author(in,"Ann")));assertValues(new Object[0],select(in,()->TaskBinding.author(in,"ann")));assertValues(new Object[]{a,a},select(in,()->TaskBinding.publisher(in,"P")));assertValues(new Object[0],select(in,()->TaskBinding.publisher(in,"p")));assertValues(new Object[]{b},select(in,()->TaskBinding.after(in,2020)));assertValues(new Object[]{a,b,a},in);assertEquals(sa,TaskBinding.state(a));assertEquals(sb,TaskBinding.state(b));assertValues(new Object[0],TaskBinding.after(TaskBinding.array(),1));} @Test void twoConstructorsAndProperties(){Object b=TaskBinding.shortBook();assertFalse(TaskBinding.text(b).isBlank());TaskBinding.edit(b);assertEquals("7|New|[Bob]|Q|2025|40|3.0|soft",TaskBinding.state(b));}static void assertValues(Object[]expected,Object[]actual){assertNotNull(actual,"подборка");assertEquals(java.util.Arrays.stream(expected).map(TaskBinding::value).toList(),java.util.Arrays.stream(actual).map(TaskBinding::value).toList(),"значения, порядок и кратность подборки; identity результата свободна");}static Object[] select(Object[]input,java.util.function.Supplier<Object[]>action){Object[]before=input.clone();var states=java.util.Arrays.stream(before).map(TaskBinding::value).toList();Object[]result=action.get();assertEquals(before.length,input.length);for(int i=0;i<before.length;i++)assertSame(before[i],input[i],"селектор изменил ячейку переданного typed массива, index="+i);assertEquals(states,java.util.Arrays.stream(input).map(TaskBinding::value).toList(),"селектор изменил поля исходных объектов");return result;}}
